import React, { useState, useEffect, useRef } from 'react';
import io from 'socket.io-client';
import { BrowserRouter as Router, Routes, Route, useNavigate, useRoutes } from 'react-router-dom';
import Meeting from './Pages/Meeting/Meeting';
import './App.css';

function MainComponent() {
  const [socket, setSocket] = useState(null);
  const [isHosting, setIsHosting] = useState(false);
  const [isJoined, setIsJoined] = useState(false);
  const [stream, setStream] = useState(null);
  const userVideo = useRef();
  const navigate = useNavigate();

  useEffect(() => {
    const newSocket = io.connect('http://localhost:3001');
    setSocket(newSocket);

    newSocket.on('host', () => {
      setIsHosting(true);
      navigate('/meeting', {
        state: {
          isMicEnabled: stream && stream.getAudioTracks()[0].enabled,
          isCamEnabled: stream && stream.getVideoTracks()[0].enabled
        }
      });
    });

    newSocket.on('join', () => {
      setIsJoined(true);
      navigate('/meeting', {
        state: {
          isMicEnabled: stream && stream.getAudioTracks()[0].enabled,
          isCamEnabled: stream && stream.getVideoTracks()[0].enabled
        }
      });
    });

    // Request access to the user's camera and microphone
    navigator.mediaDevices.getUserMedia({ video: true, audio: true })
      .then(stream => {
        // Set the source of the video element to the user's stream
        userVideo.current.srcObject = stream;
        setStream(stream);
      })
      .catch(err => {
        console.error('Error accessing media devices.', err);
      });

    return () => newSocket.close();
  }, []);

  const handleHostMeeting = () => {
    if (socket && !isHosting) {
      socket.emit('host');
    }
  };

  const handleJoinMeeting = () => {
    if (socket && !isJoined) {
      socket.emit('join');
    }
  };

  const handleMuteUnmute = () => {
    if (stream) {
      stream.getAudioTracks()[0].enabled = !stream.getAudioTracks()[0].enabled;
    }
  };

  const handleOpenCloseCamera = (videoRef) => {
    if (videoRef.current && videoRef.current.srcObject) {
      const enabled = videoRef.current.srcObject.getVideoTracks()[0].enabled;
      videoRef.current.srcObject.getVideoTracks()[0].enabled = !enabled;
    }
  };  

  let routes = useRoutes([
    {
      path: "/",
      element: (
        <div className="App">
          <main>
            <video ref={userVideo} id="userVideo" autoPlay muted></video>
            <div>
              <button id="hostButton" onClick={handleHostMeeting}>Host Meeting</button>
              <button id="joinButton" onClick={handleJoinMeeting}>Join Meeting</button>
              <button id="muteButton" onClick={handleMuteUnmute}>Mute/Unmute</button>
              <button id="cameraButton" onClick={() => handleOpenCloseCamera(userVideo)}>Open/Close Camera</button>
            </div>
          </main>
        </div>
      ),
    },
    {
      path: "/meeting",
      element: <Meeting stream={stream} handleMuteUnmute={handleMuteUnmute} handleOpenCloseCamera={handleOpenCloseCamera} />,

    },
  ]);

  return routes;
}

function App() {
  return (
    <Router>
      <MainComponent />
    </Router>
  )
}

export default App;
